#!/usr/bin/env bash
# Install the NVIDIA Container Toolkit inside a fresh kind worker and register
# the nvidia containerd runtime. Kind node images don't ship it, so this is
# needed after every `kind create cluster`. Afterwards run recreate-gpu-node.sh
# to restart the node container with Docker's --runtime=nvidia, which injects
# the host driver.
# Usage: setup-gpu-node.sh <node-name>
#
# host/nvidia-container-runtime-config.toml is the toolkit config the GPU nodes
# ran with before the Kubernetes 1.37 rebuild (goodman_reunion #881).
# 99-nvidia.toml is generated by nvidia-ctk from the new node's own containerd
# config instead of being copied, so it matches that node image.
set -euo pipefail
N=$1
VERSION=${NVIDIA_CTK_VERSION:-1.20.1-1}
HERE=$(cd "$(dirname "$0")" && pwd)
KEYRING=/usr/share/keyrings/nvidia-container-toolkit-keyring.gpg

docker exec "$N" sh -c "apt-get update -qq && apt-get install -y -qq --no-install-recommends curl gnupg ca-certificates >/dev/null"
docker exec "$N" sh -c "curl -fsSL https://nvidia.github.io/libnvidia-container/gpgkey | gpg --dearmor --yes -o $KEYRING"
docker exec "$N" sh -c "curl -fsSL https://nvidia.github.io/libnvidia-container/stable/deb/nvidia-container-toolkit.list \
  | sed 's#deb https://#deb [signed-by=$KEYRING] https://#' > /etc/apt/sources.list.d/nvidia-container-toolkit.list"
docker exec "$N" sh -c "apt-get update -qq && apt-get install -y -qq --no-install-recommends \
  nvidia-container-toolkit=$VERSION nvidia-container-toolkit-base=$VERSION \
  libnvidia-container-tools=$VERSION libnvidia-container1=$VERSION >/dev/null"
docker cp "$HERE/host/nvidia-container-runtime-config.toml" "$N:/etc/nvidia-container-runtime/config.toml"
docker exec "$N" nvidia-ctk runtime configure --runtime=containerd
docker exec "$N" systemctl restart containerd
docker exec "$N" sh -c "containerd config dump | grep -q 'runtimes.nvidia'"
echo "$N: nvidia runtime registered in containerd"
